vx, vy = float(sys.argv[1]), float(sys.argv[2])
def gold(im):
    a = np.asarray(im).astype(np.float32) / 255
    r, g, b = a[..., 0], a[..., 1], a[..., 2]
    mx, mn = a.max(2), a.min(2)
    sat = (mx - mn) / np.maximum(mx, 1e-3)
    # orange/yellow hue: r >= g > b
    hue_ok = (r >= g * 0.98) & (g > b * 1.15) & ((r - g) < 0.62 * (r - b + 1e-3))
